<?php
/**
 * Services data helper.
 * Loads data/service.json once per request and exposes small helper functions.
 */

if (!function_exists('e')) {
    function e($value): string
    {
        return htmlspecialchars((string) $value, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
    }
}

/**
 * Returns the decoded service.json (cached for the request).
 * Always returns the expected keys, even if the file is missing or invalid.
 */
function services_data(): array
{
    static $data = null;
    if ($data !== null) {
        return $data;
    }

    $data = ['settings' => [], 'listing' => [], 'cta' => [], 'services' => []];
    $file = dirname(__DIR__) . '/data/service.json';

    if (is_readable($file)) {
        $decoded = json_decode((string) file_get_contents($file), true);
        if (is_array($decoded)) {
            $data = array_merge($data, $decoded);
        }
    }
    return $data;
}

function services_all(): array
{
    return array_values(array_filter(services_data()['services'], function ($s) {
        return is_array($s) && !empty($s['slug']) && !empty($s['title']);
    }));
}

function service_find(string $slug): ?array
{
    foreach (services_all() as $service) {
        if ($service['slug'] === $slug) {
            return $service;
        }
    }
    return null;
}

function service_url(array $service): string
{
    return 'services-details.php?slug=' . rawurlencode($service['slug']);
}

/** Renders a service icon (flaticon class or inline SVG). */
function service_icon(array $service): string
{
    if (!empty($service['icon_svg'])) {
        return '<svg xmlns="http://www.w3.org/2000/svg" width="42" height="42" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">'
            . $service['icon_svg'] . '</svg>';
    }
    return '<i class="' . e($service['icon_class'] ?? 'flaticon-it-service') . '"></i>';
}

function svg_arrow(int $size = 12): string
{
    $s = (int) $size;
    return '<svg width="' . $s . '" height="' . $s . '" viewBox="0 0 12 12" fill="none" xmlns="http://www.w3.org/2000/svg">'
        . '<path d="M1 11L11 1M11 1H1M11 1V11" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>';
}

